if pC.ice>0 then
local tC=bb.rogueShare(pee[2092])
qC=qC*(tC+(1-tC)/(1-pC.ice+pC.ice/gb.modFactor(pee[2489])))
end
if pC.fly>0 then
qC=qC*(1-pC.fly*0.5)
end
