function ab.unitLabSafe(Hsb)
if O.unitLab==false or type(Hsb)~=pee[1959]or not ab.LAB.KINDS[Hsb.kind]or Hsb.first then
return false
end
if P.trial or(P.study and not P.study.done)or(type(P.testTeam)==pee[1959]and(tonumber(P.testTeam.left)or 0)>0)or(P.train and P.train.on)or ab.partyRole()~=pee[886]then
