if Ksb.pauseKey==Hsb.key and os.time()<(tonumber(Ksb.pauseUntil)or 0)then
return false
end
local Lsb=W.rec(Hsb.key)
local Msb,Nsb=tonumber(Lsb.runs)or 0,tonumber(Lsb.wins)or 0
if Hsb.kind==pee[1978]then
local Osb,Psb=pcall(W.infDaily,N.prof(),Hsb.level,W.infReach(Hsb.key))
return Msb>=3 and Osb and(tonumber(Psb)or 1)<=0
end
return Msb>=5 and(tonumber(Lsb.streak)or 0)==0 and Nsb/Msb>=0.9
end
function ab.unitLab(Qsb)
