local btb=atb.unit_id
if not Usb[_sb]and not Usb[btb]and N.Units[btb]and not V.isFarm(btb)and not V.allyBuff(btb)and os.time()-(tonumber(Rsb.tried[btb])or 0)>ab.LAB.AGAIN then
local ctb=ab.unitEvidence(btb)
if ctb<ab.LAB.MIN_EVIDENCE then
local dtb=Ssb.collection:get_unit_by_uuid(_sb)or atb
local etb=kb.score(dtb)
if etb>0 and(not Xsb or ctb<Ysb or(ctb==Ysb and etb>Zsb))then
Xsb,Ysb,Zsb={uuid=_sb,id=btb,u=dtb},ctb,etb
end
end
