function bb.buildPath()
bb.samples={}
local skc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not skc then
return
end
for tkc,ukc in pairs(skc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[tkc.Name])then
local vkc={}
for wkc,xkc in ipairs(ukc.points or{})do
table.insert(vkc,xkc.part.Position)
end
local ykc=0
for zkc=2,#vkc do
ykc=ykc+(vkc[zkc]-vkc[zkc-1]).Magnitude
end
local Akc=0
for Bkc=2,#vkc do
local Ckc,Dkc=vkc[Bkc-1],vkc[Bkc]
local Ekc=(Dkc-Ckc).Magnitude
local Fkc=math.max(1,math.floor(Ekc/2))
for Gkc=0,Fkc-1 do
local Hkc=Ckc:Lerp(Dkc,Gkc/Fkc)
table.insert(bb.samples,{pos=Hkc,prog=(Akc+Ekc*Gkc/Fkc)/math.max(1,ykc),lane=tkc.Name})
end
Akc=Akc+Ekc
end
if vkc[#vkc]then
table.insert(bb.samples,{pos=vkc[#vkc],prog=1,lane=tkc.Name})
end
end
end
pcall(bb.readHidden,skc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local Ikc=tonumber(bb.ld and bb.ld._portal_lanes)
local Jkc=gb.laneList(bb.samples)
if Ikc and Ikc>=1 and Jkc and#Jkc>Ikc then
bb.laneWant=Ikc
end
bb.laneTotal=Jkc and#Jkc or 1
bb.countLanes()
end
function bb.readHidden(Kkc)
local Lkc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(Lkc)~=pee[1959]or not next(Lkc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local Mkc
for Nkc,Okc in pairs(Kkc)do
if Lkc[Nkc.Name]and type(Okc.points)==pee[1959]and#Okc.points>=2 then
local Pkc={}
for Qkc,Rkc in ipairs(Okc.points)do
Pkc[Qkc]=U.flat(Rkc.part.Position)
end
local Skc={}
for Tkc,Ukc in ipairs(bb.samples)do
local Vkc=tostring(Ukc.lane)
Skc[Vkc]=Skc[Vkc]or{}
table.insert(Skc[Vkc],Ukc)
end
local Wkc,Xkc
for Ykc,Zkc in pairs(Skc)do
local _kc=0
for alc=1,#Pkc,math.max(1,math.floor(#Pkc/20))do
local blc=math.huge
for clc,dlc in ipairs(Zkc)do
local elc=(U.flat(dlc.pos)-Pkc[alc]).Magnitude
if elc<blc then
blc=elc
end
end
_kc=_kc+blc
end
if not Xkc or _kc<Xkc then
Wkc,Xkc=Ykc,_kc
end
end
local flc,glc,hlc,ilc,jlc,klc={},nil,nil,nil,0,0
for llc,mlc in ipairs(Pkc)do
local nlc,olc=nil,math.huge
for plc,qlc in ipairs(Skc[Wkc])do
local rlc=(U.flat(qlc.pos)-mlc).Magnitude
if rlc<olc then
olc,nlc=rlc,qlc.prog
