local Loc=U.flat(Joc)
for Moc,Noc in ipairs(bb.mine or{})do
local Ooc=Noc:FindFirstChild(pee[4012])
local Poc=Ooc and Ooc.Position or Noc:GetPivot().Position
local Qoc=Ooc and math.max(Ooc.Size.X,Ooc.Size.Z)/2 or 1.5
if(Loc-U.flat(Poc)).Magnitude<Koc+Qoc then
return nil
end
end
if not Hoc then
for Roc,Soc in ipairs(bb.blockers())do
if(Loc-Soc.p).Magnitude<Koc+Soc.r then
