Xoc=Vector3 .new(1,0,0)
end
Xoc=Xoc.Unit
local Yoc=Vector3 .new(-Xoc.Z,0,Xoc.X)
for Zoc,_oc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for apc,bpc in ipairs({1,-1})do
local cpc=Voc.pos+Yoc*_oc*bpc
