local jpc=ipc._stats
if not V.isFarm(jpc.id.Value)and jpc:FindFirstChild(pee[2211])then
table.insert(gpc,{p=U.flat(ipc:GetPivot().Position),r=jpc.range.Value*(V.SUMMONER[jpc.id.Value]and V.SUMMONER[jpc.id.Value].reach or 1),air=bb.canAir(ipc)})
