local kpc,lpc=0,0
if#gpc>0 then
for mpc,npc in ipairs(bb.samples)do
if npc.prog>lpc then
local opc=U.flat(npc.pos)
for ppc,qpc in ipairs(gpc)do
if(opc-qpc.p).Magnitude<=qpc.r then
if npc.prog>kpc then
kpc=npc.prog
