for xpc,ypc in ipairs(gpc)do
if(wpc-ypc.p).Magnitude<=ypc.r then
local zpc=tostring(vpc.lane)
tpc[zpc]=(tpc[zpc]or 0)+1
if vpc.prog>(rpc[zpc]or 0)then
rpc[zpc]=vpc.prog
end
break
end
end
end
local Apc,Bpc={},0
