if not qIc(oIc.id)or V.toggleOf(oIc.id)then
return nil
end
local rIc,sIc,tIc,uIc=1,0,0,{}
local vIc=bb.hurtSamples()
for wIc,xIc in ipairs(bb.mine or{})do
local yIc=xIc._stats
local zIc=yIc.id.Value
if yIc:FindFirstChild(pee[2211])and not V.isFarm(zIc)and not V.allyBuff(zIc)then
local AIc,BIc=U.flat(xIc:GetPivot().Position),yIc.range.Value
if qIc(zIc)and not V.toggleOf(zIc)then
tIc=tIc+1
table.insert(uIc,{p=AIc,r=BIc})
else
for CIc,DIc in ipairs(vIc)do
if(U.flat(DIc.pos)-AIc).Magnitude<=BIc then
rIc,sIc=math.min(rIc,DIc.prog),math.max(sIc,DIc.prog)
end
end
end
end
end
if sIc<=rIc then
rIc,sIc=0.75,0.98
end
local EIc=(pIc or tIc)+1
local FIc=({rIc,sIc,(rIc+sIc)/2,rIc-(sIc-rIc)/2})[EIc]
if not FIc then
return nil
end
local GIc=V.range(oIc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local HIc={}
for IIc,JIc in ipairs(bb.cands)do
local KIc,LIc,MIc=U.flat(JIc),0,0
for NIc,OIc in ipairs(vIc)do
if(U.flat(OIc.pos)-KIc).Magnitude<=GIc then
MIc=MIc+1
if math.abs(OIc.prog-FIc)<=0.05 then
LIc=LIc+1
local PIc=U.flat(OIc.pos)
for QIc,RIc in ipairs(uIc)do
if(PIc-RIc.p).Magnitude<=RIc.r then
LIc=LIc-0.5
break
end
end
end
end
end
if LIc>0 then
table.insert(HIc,{pos=JIc,sc=LIc,cov=MIc})
end
if IIc%60==0 then
task.wait()
end
end
table.sort(HIc,function(SIc,TIc)
return SIc.sc>TIc.sc
end)
for UIc,VIc in ipairs(HIc)do
local WIc=bb.valid(VIc.pos,oIc.data)
if WIc then
F.log(1,pee[4016],string.format(pee[4167],V.name(oIc.id),bb.CONTROL_WORDS[EIc],math.floor(FIc*100+0.5)))
return WIc,VIc.cov,FIc
end
if UIc%20==0 then
task.wait()
end
end
return nil
end
