local eJc=dJc.id.Value
if dJc:FindFirstChild(pee[2211])and not V.isFarm(eJc)and not V.allyBuff(eJc)and eJc~=XIc.id then
local fJc,gJc=pcall(bb.liveDps,cJc,eJc)
gJc=fJc and tonumber(gJc)or 0
if gJc>0 then
table.insert(_Ic,{p=U.flat(cJc:GetPivot().Position),r=dJc.range.Value,d=gJc})
aJc=aJc+gJc
