local HMc=P.caps[BMc.uuid]and bb.count(BMc.uuid)or nil
local IMc,JMc=F.request(pee[4171],pee[4172],BMc.uuid,N.Util.CFramePLV(EMc,bb.lookAt(EMc)))
if IMc and JMc then
if HMc and HMc>=(tonumber(P.caps[BMc.uuid])or math.huge)then
F.log(1,pee[4016],string.format(pee[4173],V.name(BMc.id),tostring(P.caps[BMc.uuid])))
P.caps[BMc.uuid],P.capsAt[BMc.uuid]=nil,nil
