for lRc,mRc in ipairs(bb.mine or{})do
local nRc=mRc._stats
local oRc=V.rows(nRc.id.Value)
local pRc=oRc and oRc[math.min(nRc.upgrade.Value,oRc.max)]
local qRc=pRc and pRc.atk and V.attackInfo(pRc.atk,pRc.range)
if qRc and((qRc.stun or 0)>0 or(qRc.slowTime or 0)>0)then
kRc=kRc+1
end
end
local rRc,sRc=gb.mask(bb.info.map,V.range(hRc.u,0)*(bb.info.rangeScale or 1)),0
for tRc=1,gb.BINS do
