function bb.buffGain(wRc)
local xRc=V.allyBuff(wRc.id)
if not xRc then
return 0
end
local yRc=bb.buffShort(xRc)
local zRc=P.stack[xRc.attack]
local ARc=zRc and zRc.stacks and(zRc.cap or 1)or nil
local BRc,CRc=pcall(V.range,wRc.u,0)
CRc=(BRc and tonumber(CRc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local DRc=ARc and O.community and tonumber(xRc.time)and tonumber(xRc.cd)
local function ERc(FRc,GRc)
local HRc=math.floor(FRc*xRc.time/math.max(1,xRc.cd)+0.001)
return math.min(ARc,(1+GRc)^HRc-1)
end
local IRc=0
for JRc,KRc in ipairs(yRc)do
local LRc=0
for MRc,NRc in ipairs(yRc)do
if(NRc.pos-KRc.pos).Magnitude<=CRc then
local ORc=xRc.types[NRc.base]
local PRc=ORc*xRc.uptime
if DRc then
local QRc,RRc=ERc(NRc.n,ORc),NRc.n+1
while RRc<NRc.n+6 and ERc(RRc,ORc)<=QRc+0.001 do
RRc=RRc+1
end
PRc=math.max(0,(ERc(RRc,ORc)-QRc)/(RRc-NRc.n))
elseif ARc then
PRc=math.max(0,math.min(ARc,(NRc.n+1)*ORc*xRc.uptime)-math.min(ARc,NRc.n*ORc*xRc.uptime))
end
LRc=LRc+NRc.dps*PRc
end
end
IRc=math.max(IRc,LRc)
