local M6c,N6c=0,0
local O6c,P6c=H6c.foes or{},I6c.foes or{}
for Q6c,R6c in pairs(P6c)do
if R6c.prog>=bb.BASE_END then
M6c=M6c+R6c.hp
local S6c=O6c[Q6c]
if S6c then
N6c=N6c+math.max(0,S6c.hp-R6c.hp)
end
end
end
for T6c,U6c in pairs(O6c)do
if U6c.prog>=bb.BASE_END and not P6c[T6c]then
N6c=N6c+U6c.hp
end
end
if M6c<=0 then
return false
end
local V6c=N6c/J6c
local W6c=V6c>0 and M6c/V6c or math.huge
local X6c={baseTime=L6c,loss=K6c,atEnd=M6c,rate=V6c,killTime=W6c}
return L6c<bb.BASE_SOON and W6c>L6c*bb.BASE_MARGIN,X6c
end
